 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    # Treat isolated one-cell components as speckle; replace with the local
    # surrounding color, using the 8-neighborhood majority.
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            if len(comp) != 1:
                continue
            y, x = comp[0]
            neighbors = [grid[yy][xx]
                         for yy in range(max(0,y-1), min(h,y+2))
                         for xx in range(max(0,x-1), min(w,x+2))
                         if (yy,xx) != (y,x)]
            if neighbors:
                counts = Counter(neighbors)
                best = max(counts.values())
                # Deterministic tie break by first appearance in row-major neighborhood.
                out[y][x] = next(v for v in neighbors if counts[v] == best)
    return out
