from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    # Isolated marked cells are repaired by local neighborhood majority.
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            if len(comp) != 1:
                continue
            y, x = comp[0]
            neighbors = [grid[yy][xx]
                         for yy, xx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1))
                         if 0 <= yy < h and 0 <= xx < w]
            if neighbors:
                counts = Counter(neighbors)
                best = max(counts.values())
                out[y][x] = next(v for v in neighbors if counts[v] == best)
