 "content": "from collections import Counter, defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    comps_by_color = defaultdict(list)
    singletons = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            rs = [y for y,x in cells]; cs = [x for y,x in cells]
            box = (min(rs), max(rs), min(cs), max(cs))
            area = (box[1]-box[0]+1)*(box[3]-box[2]+1)
            meta = (cells, box, area, len(cells)/area)
            comps_by_color[color].append(meta)
            if len(cells) == 1:
                singletons.append((color, cells[0]))

    for color, (y,x) in singletons:
        neighbors = [(yy,xx) for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)) if 0<=yy<h and 0<=xx<w]
        if not neighbors:
            continue
        vals = [grid[yy][xx] for yy,xx in neighbors]
        counts = Counter(vals)
        best = max(counts.values())
        tied = {v for v,n in counts.items() if n == best}
        if len(tied) == 1:
            out[y][x] = next(iter(tied))
            continue
        # If a neighboring color's coherent region spans the speck location,
        # restore that interrupted rectangle; otherwise it is a background gap.
        covering = []
        for v in tied:
            for cells, box, area, density in comps_by_color[v]:
                r0,r1,c0,c1 = box
                if len(cells) >= 2 and r0 <= y <= r1 and c0 <= x <= c1:
                    covering.append((area, -len(cells), v))
        if covering:
            out[y][x] = min(covering)[2]
        else:
            # Deterministic tie break: left, right, up, down.
            out[y][x] = vals[2] if len(vals) > 2 else vals[0]
    return out
"
}

